void flip(int a[], int n)
{
    for (int i = 0; i < n / 2; i++) {
        int t = a[i];
        a[i] = a[n - 1 - i];
        a[n - 1 - i] = t;
    }
}
int main()
{
    int v[5] = {1, 2, 3, 4, 5};
    flip(v, 5);
    for (int i = 0; i < 5; i++)
        cout << v[i] << ' ';
    return 0;
}

