#include <iostream>
#include <iomanip>
#include <string>
#include <vector>
using namespace std;

int main()
{
    const int MAX = 20;
    int a[MAX];
    int n;
    cin >> n;
    for (int i = 0; i < n; i++)
        cin >> a[i];

    int sum = 0, hi = a[0], hiPos = 0, lo = a[0], loPos = 0;
    for (int i = 0; i < n; i++) {
        sum += a[i];
        if (a[i] > hi) { hi = a[i]; hiPos = i; }
        if (a[i] < lo) { lo = a[i]; loPos = i; }
    }
    double avg = static_cast<double>(sum) / n;
    int above = 0;
    for (int i = 0; i < n; i++)
        if (a[i] > avg)
            above++;

    cout << fixed << setprecision(2);
    cout << "Sum: " << sum << endl;
    cout << "Average: " << avg << endl;
    cout << "Highest: " << hi << " at " << hiPos << endl;
    cout << "Lowest: " << lo << " at " << loPos << endl;
    cout << "Above average: " << above << endl;
    return 0;
}

