        cin >> v[i];
    cout << "Even values: " << countEven(v, SIZE) << endl;
    reverseArray(v, SIZE);
    cout << "Reversed:";
    for (int i = 0; i < SIZE; i++)
        cout << " " << v[i];
    cout << endl;
    return 0;
}

